// 1. تحديد ما إذا كان الحدث ضغطة زر أم رسالة عادية (مع دعم البيانات القادمة من Edit Fields أو تيليجرام)
const isCallback = !!$json.callback_query;
const callbackQuery = $json.callback_query || null;

const updateId = $json.update_id || $json.updata_id || null;
const message = isCallback ? (callbackQuery.message || {}) : ($json.message || null);

// 2. استخراج بيانات العميل والشات بأمان للحالتين (دعم Edit Fields المباشر أو البنية الخام)
const userObj = isCallback ? (callbackQuery.from || {}) : ($json.user_id ? { id: $json.user_id, first_name: $json.name } : (message.from || {}));
const chatId = $json.chat_id || (isCallback ? callbackQuery.message?.chat?.id : (message.chat?.id || userObj.id)) || null;
const userId = $json.user_id || userObj.id || null;
const firstName = $json.name || userObj.first_name || 'Customer';

// استخراج النص بمرونة (سواء من Edit Fields المباشر أو من رسالة تيليجرام)
const rawText = ($json.text || message?.text || '').trim();

// 3. مسار التعامل مع ضغطات الأزرار التفاعلية (Callback Query)
if (isCallback) {
  return [{
    json: {
      is_callback: true,
      callback_query_id: callbackQuery.id,
      callback_data: callbackQuery.data,
      user_id: userId,
      chat_id: chatId,
      first_name: firstName,
      name: firstName,
      update_id: updateId,
      idempotency_key: `cb_${callbackQuery.id}`
    }
  }];
}

// 4. مسار التعامل مع الرسائل النصية (إهمال غير النصية)
if (!rawText || !chatId) {
  return []; // إهمال الرسائل غير النصية أو الفارغة
}

// 5. استخراج الـ Tag الخاص بـ RAG (مثل Q1, Q2) إن وجد
const qMatch = rawText.match(/(?:[\s?#,-]*)\b([qQ][1-5])\b/i);
const cleanText = qMatch ? rawText.replace(qMatch[0], '').trim() : rawText;
const targetNamespace = qMatch ? qMatch[1].toUpperCase() : null;

return [{
  json: {
    is_callback: false,
    update_id: updateId,
    chat_id: chatId,
    user_id: userId,
    name: firstName,
    first_name: firstName,
    text: cleanText,
    raw_text: rawText,
    target_namespace: targetNamespace,
    idempotency_key: `msg_${updateId || Date.now()}_${chatId}`
  }
}];

