// 1. استخراج محتوى الـ LLM بأمان مع التعامل مع صيغ الـ JSON أو الـ Markdown
let rawContent = $json.choices?.[0]?.message?.content || '{}';

if (typeof rawContent === 'string') {
  // تنظيف النص في حال وجود ```json ... ```
  rawContent = rawContent.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
}

let responseContent = {};
try {
  responseContent = typeof rawContent === 'string' ? JSON.parse(rawContent) : rawContent;
} catch (e) {
  responseContent = {
    confidence: 0,
    needs_escalation: true,
    intent: 'unknown',
    answer: typeof rawContent === 'string' ? rawContent : 'لم أتمكن من العثور على الإجابة المناسبة.'
  };
}

const confidence = responseContent.confidence || 0;
const needsEscalation = responseContent.needs_escalation ?? false;
const intent = responseContent.intent || 'unknown';
const answer = responseContent.answer || 'لم أتمكن من العثور على الإجابة المناسبة.';

// 2. تطبيق شرط القرار والتصعيد بناءً على الثقة
const isHighConfidence = (confidence >= 0.75) && !needsEscalation && (intent !== 'human_escalation_request');

// 3. جلب بيانات التوكنز من عقدة OpenAI
const openAiUsage = $('LLM Reasoning & Intent Classification').first()?.json?.usage || {};
const promptTokens = openAiUsage.prompt_tokens || 0;
const completionTokens = openAiUsage.completion_tokens || 0;
const totalTokens = openAiUsage.total_tokens || 0;

// 4. حساب التكاليف الفعلية (USD)
// gpt-4o-mini: $0.15 / 1M input, $0.60 / 1M output
const llmCost = (promptTokens * (0.15 / 1000000)) + (completionTokens * (0.60 / 1000000));

// text-embedding-3-small (تقديري لـ 50 token): $0.02 / 1M input
const embeddingCost = 50 * (0.02 / 1000000); 

// Cohere Rerank v3.5: $2.00 لكل 1,000 استعلام ($0.002 لكل طلب)
const rerankCost = 0.002;

// إجمالي تكلفة الاستعلام الواحد بالدولار
const totalQueryCost = llmCost + embeddingCost + rerankCost;

// حالة منع التصعيد / نجاح البوت (Deflection Status)
const isDeflected = !needsEscalation;

// 5. إرجاع النتيجة النهائية جاهزة للتخزين في Supabase
return [{
  json: {
    ...$json,
    is_high_confidence: isHighConfidence,
    needs_escalation: needsEscalation,
    confidence: confidence,
    intent: intent,
    answer: answer,
    chat_id: $('Extract Message & Idempotency Key').first()?.json?.chat_id,
    conversation_id: $('Upsert Customer & Log Message').first()?.json?.conversation_id,
    prompt_tokens: promptTokens,
    completion_tokens: completionTokens,
    total_tokens: totalTokens,
    estimated_cost_usd: Number(totalQueryCost.toFixed(6)),
    is_deflected: isDeflected
  }
}];

