// جلب مخرجات استعلام الكاش من Supabase
const cacheResult = $input.all();

// جلب السؤال الأصلي وبيانات المحادثة من الخطوات السابقة (تأكد من تطابق اسم العقدة لديك)
const originalText = $('Extract Message & Idempotency Key').first().json.text;
const chatId = $('Extract Message & Idempotency Key').first().json.chat_id;
const conversationId = $('Upsert Customer & Log Message').first().json.conversation_id;
const namespace = $('Message a model').first().json.output[0].content[0].text.namespace

// التحقق مما إذا كان الاستعلام قد أرجع إجابة مخزنة
if (cacheResult && cacheResult.length > 0 && cacheResult[0].json && cacheResult[0].json.answer) {
  // --- حالة وجود كاش (Cache Hit) ---
  return [{
    json: {
      from_cache: true,
      answer: cacheResult[0].json.answer,
      text: originalText,
      chat_id: chatId,
      conversation_id: conversationId,
      total_tokens: 0,
      estimated_cost_usd: 0,
      is_deflected: true
    }
  }];
} else {
  // --- حالة عدم وجود كاش (Cache Miss) - سؤال جديد ---
  return [{
    json: {
      from_cache: false,
      text: originalText,
      chat_id: chatId,
      conversation_id: conversationId,
      namespace : namespace
    }
  }];
}
